// HERMES Tracking — Parse Resend webhook event
const body = $json.body || $json;
const type = body.type || '';
const data = body.data || {};

// Extract lead_id from Resend tags
const tags = data.tags || {};
const leadId = tags.lead_id || '';
const resendId = data.email_id || data.id || '';

if (!leadId || !type) {
  return [{ json: { skip: true, reason: 'No lead_id or type', type, tags } }];
}

// Map event type → Airtable field update
const fieldMap = {
  'email.opened':      { field: 'Email_Abierto', value: true,  tg: '👁️ Email ABIERTO' },
  'email.clicked':     { field: 'Email_Click',   value: true,  tg: '🖱️ Email CLICKEADO' },
  'email.bounced':     { field: 'Email_Bounce',  value: true,  tg: '🔴 Email BOUNCE' },
  'email.complained':  { field: 'Email_Bounce',  value: true,  tg: '⚠️ Email SPAM REPORT' },
  'email.unsubscribed':{ field: 'Unsubscribed',  value: true,  tg: '🚫 UNSUBSCRIBE' },
};

const mapping = fieldMap[type];
if (!mapping) {
  return [{ json: { skip: true, reason: 'Unmapped event type', type } }];
}

return [{ json: {
  skip:     false,
  lead_id:  leadId,
  resend_id: resendId,
  event:    type,
  field:    mapping.field,
  value:    mapping.value,
  tg_label: mapping.tg,
  email_to: (data.to || []).join(', '),
} }];
